// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 _val) public {
        bool ok;
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(c.MinSum() == _val);
        } else {
            assertTrue(false);
        }
    }
}
